CREATE TABLE user_accounts (id uuid PRIMARY KEY, email varchar(180) UNIQUE NOT NULL, password_hash varchar(100) NOT NULL, display_name varchar(120) NOT NULL, role varchar(30) NOT NULL, client_id uuid, enabled boolean NOT NULL, created_at timestamptz NOT NULL);
CREATE TABLE app_sessions (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES user_accounts(id), expires_at timestamptz NOT NULL, revoked boolean NOT NULL);
CREATE TABLE reset_tokens (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES user_accounts(id), token_hash varchar(64) UNIQUE NOT NULL, expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE clients (id uuid PRIMARY KEY, name varchar(160) NOT NULL, type varchar(20) NOT NULL, email varchar(180) NOT NULL, phone varchar(40), address varchar(400), conflict_metadata varchar(1000), status varchar(30) NOT NULL, created_at timestamptz NOT NULL);
CREATE TABLE practice_areas (id uuid PRIMARY KEY, name varchar(100) UNIQUE NOT NULL, active boolean NOT NULL);
CREATE TABLE matters (id uuid PRIMARY KEY, reference varchar(30) UNIQUE NOT NULL, title varchar(200) NOT NULL, client_id uuid NOT NULL REFERENCES clients(id), practice_area varchar(100) NOT NULL, attorney_id uuid REFERENCES user_accounts(id), paralegal_id uuid REFERENCES user_accounts(id), status varchar(30) NOT NULL, sensitivity varchar(30) NOT NULL, description varchar(3000), opened_on date, target_close_date date, updated_at timestamptz NOT NULL);
CREATE TABLE documents (id uuid PRIMARY KEY, matter_id uuid NOT NULL REFERENCES matters(id), name varchar(220) NOT NULL, category varchar(40) NOT NULL, visibility varchar(30) NOT NULL, tags varchar(500), current_version integer NOT NULL, uploaded_by uuid NOT NULL REFERENCES user_accounts(id), created_at timestamptz NOT NULL);
CREATE TABLE document_versions (id uuid PRIMARY KEY, document_id uuid NOT NULL REFERENCES documents(id), version integer NOT NULL, original_name varchar(220) NOT NULL, storage_name varchar(180) NOT NULL, content_type varchar(100) NOT NULL, size_bytes bigint NOT NULL, checksum varchar(64) NOT NULL, uploaded_by uuid NOT NULL REFERENCES user_accounts(id), created_at timestamptz NOT NULL, UNIQUE(document_id, version));
CREATE TABLE task_items (id uuid PRIMARY KEY, matter_id uuid NOT NULL REFERENCES matters(id), title varchar(220) NOT NULL, notes varchar(2000), assignee_id uuid REFERENCES user_accounts(id), priority varchar(20) NOT NULL, status varchar(30) NOT NULL, due_date date, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE TABLE deadlines (id uuid PRIMARY KEY, matter_id uuid NOT NULL REFERENCES matters(id), title varchar(220) NOT NULL, due_at timestamptz NOT NULL, responsible_id uuid REFERENCES user_accounts(id), reminder_days integer NOT NULL, completed boolean NOT NULL, reminder_sent boolean NOT NULL);
CREATE TABLE note_messages (id uuid PRIMARY KEY, matter_id uuid NOT NULL REFERENCES matters(id), author_id uuid NOT NULL REFERENCES user_accounts(id), kind varchar(30) NOT NULL, body varchar(5000) NOT NULL, status varchar(30) NOT NULL, created_at timestamptz NOT NULL, approved_by uuid REFERENCES user_accounts(id));
CREATE TABLE notifications (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES user_accounts(id), title varchar(180) NOT NULL, body varchar(800) NOT NULL, link varchar(400), read_at timestamptz, created_at timestamptz NOT NULL);
CREATE TABLE audit_events (id uuid PRIMARY KEY, actor_id uuid, action varchar(100) NOT NULL, resource_type varchar(80) NOT NULL, resource_id varchar(80), before_value text, after_value text, authorization_basis varchar(300) NOT NULL, occurred_at timestamptz NOT NULL);
CREATE TABLE settings (setting_key varchar(100) PRIMARY KEY, setting_value varchar(500) NOT NULL, updated_at timestamptz NOT NULL);
CREATE TABLE api_keys (id uuid PRIMARY KEY, name varchar(100) NOT NULL, key_hash varchar(64) NOT NULL, prefix varchar(16) NOT NULL, enabled boolean NOT NULL, created_at timestamptz NOT NULL);
CREATE TABLE webhook_deliveries (id uuid PRIMARY KEY, event_type varchar(100) NOT NULL, target_url varchar(400) NOT NULL, status varchar(30) NOT NULL, response_code integer, attempted_at timestamptz NOT NULL);
CREATE TABLE outbox (id uuid PRIMARY KEY, recipient varchar(180) NOT NULL, subject varchar(200) NOT NULL, body varchar(4000) NOT NULL, status varchar(30) NOT NULL, created_at timestamptz NOT NULL);
CREATE INDEX idx_matters_client ON matters(client_id); CREATE INDEX idx_docs_matter ON documents(matter_id); CREATE INDEX idx_tasks_matter ON task_items(matter_id); CREATE INDEX idx_deadlines_due ON deadlines(due_at); CREATE INDEX idx_audit_time ON audit_events(occurred_at DESC);

